52	/**
53	 * @author Vitaliy Fedoriv
54	 */
55	
56	@RestController
57	@CrossOrigin(exposedHeaders = "errors, content-type")
58	@RequestMapping("/api")
59	public class OwnerRestControllerV1 implements OwnersApi {
60	
61	    private final ClinicService clinicService;
62	
63	    private final OwnerMapper ownerMapper;
64	
65	    private final PetMapper petMapper;
66	
67	    private final VisitMapper visitMapper;
68	
69	    public OwnerRestControllerV1(ClinicService clinicService,
70	                                 OwnerMapper ownerMapper,
71	                                 PetMapper petMapper,
72	                                 VisitMapper visitMapper) {
73	        this.clinicService = clinicService;
74	        this.ownerMapper = ownerMapper;
75	        this.petMapper = petMapper;
76	        this.visitMapper = visitMapper;
77	    }
78	
79	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
80	    @Override
81	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
82	        Collection<Owner> owners;
83	        if (lastName != null) {
84	            owners = this.clinicService.findOwnerByLastName(lastName);
85	        } else {
86	            owners = this.clinicService.findAllOwners();
87	        }
88	        if (owners.isEmpty()) {
89	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
90	        }
91	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
92	    }
93	
94	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
95	    @Override
96	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
97	        Owner owner = this.clinicService.findOwnerById(ownerId);
98	        if (owner == null) {
99	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
100	        }
101	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
102	    }
103	
104	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
105	    @Override
106	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
107	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
108	        if (normalizedTelephone == null) {
109	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
110	        }
111	        String normalizedAddress = Owner.normalizeAddress(ownerFieldsDto.getAddress());
112	        if (normalizedAddress == null || normalizedAddress.isBlank()) {
113	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
114	        }
115	        if (!this.clinicService.findOwnerByTelephone(normalizedTelephone).isEmpty()) {
116	            return new ResponseEntity<>(HttpStatus.CONFLICT);
117	        }
118	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
119	        List<Owner> householdMembers =
120	            findHouseholdMembers(ownerFieldsDto.getLastName(), normalizedAddress);
121	        if (!sharesHousehold && !householdMembers.isEmpty()) {
122	            return new ResponseEntity<>(HttpStatus.CONFLICT);
123	        }
124	        HttpHeaders headers = new HttpHeaders();
125	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
126	        owner.setTelephone(normalizedTelephone);
127	        if (owner.getRegistrationDate() == null) {
128	            owner.setRegistrationDate(LocalDate.now());
129	        }
130	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
131	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
132	        if (sharesHousehold && !householdMembers.isEmpty()) {
133	            String householdId = householdId(owner.getLastName(), normalizedAddress);
134	            owner.setHouseholdId(householdId);
135	            for (Owner member : householdMembers) {
136	                if (member.getHouseholdId() == null || member.getHouseholdId().isBlank()) {
137	                    member.setHouseholdId(householdId);
138	                    this.clinicService.saveOwner(member);
139	                }
140	            }
141	        }
142	        this.clinicService.saveOwner(owner);
143	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
144	        headers.setLocation(UriComponentsBuilder.newInstance()
145	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
146	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
147	    }
148	
149	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
150	    @Override
151	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
152	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
153	        if (currentOwner == null) {
154	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
155	        }
156	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
157	        if (normalizedTelephone == null) {
158	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
159	        }
160	        currentOwner.setAddress(ownerFieldsDto.getAddress());
161	        currentOwner.setCity(ownerFieldsDto.getCity());
162	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
163	        currentOwner.setLastName(ownerFieldsDto.getLastName());
164	        currentOwner.setTelephone(normalizedTelephone);
165	        currentOwner.setEmail(ownerFieldsDto.getEmail());
166	        this.clinicService.saveOwner(currentOwner);
167	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
168	    }
169	
170	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
171	    @Transactional
172	    @Override
173	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
174	        Owner owner = this.clinicService.findOwnerById(ownerId);
175	        if (owner == null) {
176	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
177	        }
178	        this.clinicService.deleteOwner(owner);
179	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
180	    }
181	
182	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
183	    @Override
184	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
185	        Owner owner = this.clinicService.findOwnerById(ownerId);
186	        if (owner == null) {
187	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
188	        }
189	        HttpHeaders headers = new HttpHeaders();
190	        Pet pet = petMapper.toPet(petFieldsDto);
191	        owner.setId(ownerId);
192	        pet.setOwner(owner);
193	        pet.getType().setName(null);
194	        this.clinicService.savePet(pet);
195	        PetDto petDto = petMapper.toPetDto(pet);
196	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
197	            .buildAndExpand(pet.getId()).toUri());
198	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
199	    }
200	
201	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
202	    @Override
203	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
204	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
205	        if (currentOwner != null) {
206	            Pet currentPet = this.clinicService.findPetById(petId);
207	            if (currentPet != null) {
208	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
209	                currentPet.setName(petFieldsDto.getName());
210	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
211	                this.clinicService.savePet(currentPet);
212	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
213	            }
214	        }
215	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
216	    }
217	
218	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
219	    @Override
220	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
221	        HttpHeaders headers = new HttpHeaders();
222	        Visit visit = visitMapper.toVisit(visitFieldsDto);
223	        Pet pet = new Pet();
224	        pet.setId(petId);
225	        visit.setPet(pet);
226	        this.clinicService.saveVisit(visit);
227	        VisitDto visitDto = visitMapper.toVisitDto(visit);
228	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
229	            .buildAndExpand(visit.getId()).toUri());
230	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
231	    }
232	
233	
234	    /**
235	     * Normalize a telephone number to E.164 form. Spaces, dashes and brackets are
236	     * stripped. When a leading {@code '+'} and country code are present they are kept;
237	     * otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
238	     * is dropped from the national digits. The result must be a {@code '+'} followed
239	     * by 8 to 15 digits, and is returned as {@code +<digits>}; otherwise {@code null}
240	     * is returned to signal a bad request.
241	     */
242	    /**
243	     * Build the customer code for a newly created owner, formatted
244	     * {@code '<CITY3>-<LAST3>-<NNNN>'} where {@code CITY3} is the upper-cased first
245	     * three letters of the city, {@code LAST3} the upper-cased first three letters of
246	     * the last name, and {@code NNNN} a per-city 4-digit zero-padded sequence equal to
247	     * one more than the number of owners already in that city.
248	     */
249	    private String nextCustomerCode(String city, String lastName) {
250	        String cityPrefix = prefixThree(city);
251	        String lastNamePrefix = prefixThree(lastName);
252	        String normalizedCity = normalizeForHousehold(city);
253	        int sequence = (int) this.clinicService.findAllOwners().stream()
254	            .filter(existing -> normalizeForHousehold(existing.getCity()).equals(normalizedCity))
255	            .count() + 1;
256	        return String.format("%s-%s-%04d", cityPrefix, lastNamePrefix, sequence);
257	    }
258	
259	    /** Upper-cased first three letters of {@code value} (fewer if shorter, empty if null). */
260	    private String prefixThree(String value) {
261	        String v = value == null ? "" : value;
262	        return v.substring(0, Math.min(3, v.length())).toUpperCase(Locale.ROOT);
263	    }
264	
265	    /**
266	     * Find the existing owners that already belong to the same household as the given
267	     * last name and address, i.e. those sharing both fields. Both are compared
268	     * case-insensitively after collapsing runs of whitespace to a single space and
269	     * trimming the ends.
270	     */
271	    private List<Owner> findHouseholdMembers(String lastName, String address) {
272	        String normalizedLastName = normalizeForHousehold(lastName);
273	        String normalizedAddress = normalizeForHousehold(address);
274	        return this.clinicService.findAllOwners().stream()
275	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
276	                && normalizeForHousehold(existing.getAddress()).equals(normalizedAddress))
277	            .toList();
278	    }
279	
280	    /**
281	     * Count the existing owners that already share both the given first and last
282	     * name, compared case-insensitively. Used to populate an owner's namesake count
283	     * at creation time, reflecting how many owners with the same name existed before
284	     * this one was created.
285	     */
286	    private int countNamesakes(String firstName, String lastName) {
287	        String normalizedFirstName = normalizeName(firstName);
288	        String normalizedLastName = normalizeName(lastName);
289	        return (int) this.clinicService.findAllOwners().stream()
290	            .filter(existing -> normalizeName(existing.getFirstName()).equals(normalizedFirstName)
291	                && normalizeName(existing.getLastName()).equals(normalizedLastName))
292	            .count();
293	    }
294	
295	    private String normalizeName(String value) {
296	        return value == null ? "" : value.toLowerCase(Locale.ROOT);
297	    }
298	
299	    /**
300	     * Build a stable identifier shared by all owners of one household. It is derived
301	     * deterministically from the normalized last name and address, so every owner at
302	     * the same household resolves to the same value regardless of creation order.
303	     */
304	    private String householdId(String lastName, String address) {
305	        String key = normalizeForHousehold(lastName) + "\n" + normalizeForHousehold(address);
306	        try {
307	            byte[] digest = MessageDigest.getInstance("SHA-256")
308	                .digest(key.getBytes(StandardCharsets.UTF_8));
309	            StringBuilder sb = new StringBuilder();
310	            for (int i = 0; i < 6; i++) {
311	                sb.append(String.format("%02X", digest[i]));
312	            }
313	            return "HH-" + sb;
314	        }
315	        catch (NoSuchAlgorithmException e) {
316	            throw new IllegalStateException(e);
317	        }
318	    }
319	
320	    private String normalizeForHousehold(String value) {
321	        if (value == null) {
322	            return "";
323	        }
324	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
325	    }
326	
327	    private String normalizeTelephone(String telephone) {
328	        if (telephone == null) {
329	            return null;
330	        }
331	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
332	        String digits;
333	        if (cleaned.startsWith("+")) {
334	            digits = cleaned.substring(1);
335	        } else {
336	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
337	            digits = "61" + national;
338	        }
339	        return digits.matches("[0-9]{8,15}") ? "+" + digits : null;
340	    }
341	
342	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
343	    @Override
344	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
345	        Owner owner = this.clinicService.findOwnerById(ownerId);
346	        if (owner != null) {
347	            Pet pet = owner.getPet(petId);
348	            if (pet != null) {
349	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
350	            }
351	        }
352	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
353	    }
354	}
